from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[1]
assert not (R/'out/VALIDATION.json').exists(),'Full job already passed; no suffix needed'
cp=json.loads((R/'out/CHECKPOINT.json').read_text());n=cp['core_masks_finished']
assert 0<n<256 and cp['query_cases']==3*n
code=R/'code/check.py';raw=code.read_bytes()
(R/'code/check_v3_full_timeout.py').write_bytes(raw)
(R/'out/PREFIX_CERTIFICATE.json').write_text(json.dumps({'status':'PASS_COMPLETED_PREFIX','helper':'code/check_v3_full_timeout.py','helper_sha256':hashlib.sha256(raw).hexdigest(),'domain':f'masks0..{n-1}, all3 query coordinates','actual_core_masks':n,'query_cases':3*n,'exact_assertions':cp['assertions'],'runtime_checkpoint_seconds':cp['elapsed_seconds'],'evidence':'Completed per-mask flushed checkpoint after all inequalities and interval computations. Full job stopped only at frozen runtime, not a failed mathematical assertion. Uncheckpointed last mask excluded and may be replayed once in suffix. Prefix individual margin records were in-memory and not persisted at timeout; the exact assertions, completed count and byte-pinned deterministic checker are the prefix proof receipt.','checkpoint':cp},indent=2)+'\n',encoding='utf-8')
s=code.read_text(encoding='utf-8')
s=s.replace("PILOT='--pilot' in sys.argv; CAP=58 if PILOT else 595", "PILOT='--pilot' in sys.argv; CAP=58 if PILOT else 595\nSTART_MASK=int(next((arg.split('=')[1] for arg in sys.argv if arg.startswith('--start-mask=')),'0'))\nSTOP_MASK=int(next((arg.split('=')[1] for arg in sys.argv if arg.startswith('--stop-mask=')),'256'))")
s=s.replace("if PILOT else list(range(256))", "if PILOT else list(range(START_MASK,STOP_MASK))")
s=s.replace("('PILOT.json' if PILOT else 'VALIDATION.json')", "('PILOT.json' if PILOT else 'VALIDATION_SUFFIX.json' if START_MASK else 'VALIDATION_PREFIX_REPLAY.json' if STOP_MASK<256 else 'VALIDATION.json')")
s+= '''\nif START_MASK and STOP_MASK==256:\n prefix=json.loads((R/'out/PREFIX_CERTIFICATE.json').read_text())\n assert prefix['actual_core_masks']==START_MASK\n merged={k:v for k,v in result.items() if k!='records'}\n merged.update({'actual_core_masks':256,'query_cases':768,'exact_assertions':prefix['exact_assertions']+COUNT,'runtime_seconds':prefix['runtime_checkpoint_seconds']+result['runtime_seconds'],'reference_only_data_nodes':'Prefix total unrecorded; suffix observed '+str(refonlycount),'split_receipts':['PREFIX_CERTIFICATE.json','VALIDATION_SUFFIX.json'],'prefix_helper_sha256':prefix['helper_sha256'],'prefix_individual_margin_records':'not persisted at runtime stop; byte-pinned exact assertion receipt retained','suffix_first_mask':START_MASK})\n (R/'out/VALIDATION.json').write_text(json.dumps(merged,indent=2)+'\\n',encoding='utf-8')\n print(json.dumps({'merged_status':'PASS','actual_core_masks':256,'query_cases':768,'exact_assertions':merged['exact_assertions']},indent=2))\n'''
code.write_text(s,encoding='utf-8')
spec={'helper_version':'A064-paid-two-conversion-nonflat-v4-suffix','helper_sha256':hashlib.sha256(code.read_bytes()).hexdigest(),'actual_family':'Unchanged original Boolean source family and both actual branches, all3 selected data coordinates','domain':f'masks{n}..255 inclusive only','case_count':3*(256-n),'prefix_not_repeated':f'masks0..{n-1} completed and preserved in PREFIX_CERTIFICATE','arithmetic':'Same v3 exact Fraction/root/log intervals, no proof/domain change','memory_estimate_MB':100,'max_runtime_seconds':595,'symmetry':'None','maximum_dimension':6,'command':'python -X utf8 '+str(code)+' --start-mask='+str(n),'prefix_regeneration_command':'python -X utf8 '+str(code)+' --stop-mask='+str(n),'stop_reason':'Initial full job reached frozen595-second cap; completed prefix preserved, only uncompleted domain resumed'}
(R/'out/FROZEN_SUFFIX_SPEC.json').write_text(json.dumps(spec,indent=2)+'\n',encoding='utf-8')
print(json.dumps(spec,indent=2))
